#pragma once
#include "SoundState.h"

namespace glitchkid
{
// The starting profiles: lists of parameter overrides applied on top of the Factory Default sound, so every sound parameter is always set and a profile sounds
// the same whatever the plug-in was doing before. They use only existing parameters (EQ, compressor, saturation, echo, Dimension, Doubler). Pitch Tune (on,
// strength, speed, key, scale) is NEVER part of a profile: it belongs to the user (the TUNE screen). The table is generated by tools/gen_profiles.py into
// Profiles.inc. These are original starting points, not presets of anyone's voice or recording chain.
namespace FactoryPresets
{
    constexpr int count = 8;

    struct Info
    {
        const char* name;        // shown in the preset menu and the preset bar, e.g. "MODERN MELODIC RAP"
        const char* tagline;     // a few words for the card
        const char* description; // the intended character, in plain words
        const char* settings;    // what the profile actually does (generated from its values)
        const char* startWith;   // a suggested starting point for the user's vocal
    };

    const Info& info (int index);                                       // index 0..count-1
    int indexOfName (const juce::String& name);                         // case-insensitive; -1 if not a factory profile
    SoundState build (int index, const SoundState& factoryDefault);     // defaults + this profile's overrides
    struct Override { const char* id; float value; };
    int numOverrides (int index);
    const Override* overrides (int index);
}
}
